<?php $pageTitle='Standings';require_once __DIR__.'/includes/header.php';$t=active_tournament($pdo);$sql="SELECT p.id,p.name,p.institution,COUNT(m.id) played,COALESCE(SUM(m.winner_id=p.id),0) wins,COALESCE(SUM(m.winner_id<>p.id),0) losses,COALESCE(SUM(CASE WHEN m.participant1_id=p.id THEN m.score1 ELSE m.score2 END),0) score_for,COALESCE(SUM(CASE WHEN m.participant1_id=p.id THEN m.score2 ELSE m.score1 END),0) score_against FROM participants p LEFT JOIN matches m ON m.status='finished' AND (m.participant1_id=p.id OR m.participant2_id=p.id) WHERE p.tournament_id=? GROUP BY p.id ORDER BY wins DESC,(score_for-score_against) DESC,score_for DESC";$s=$pdo->prepare($sql);$s->execute([$t['id']??0]);?>
<main><section class="page-hero"><div class="container"><div class="eyebrow">Performance table</div><h1>Standings</h1><p>Calculated automatically from completed matches.</p></div></section><section class="section"><div class="container"><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Participant</th><th>Played</th><th>Win</th><th>Loss</th><th>Score For</th><th>Score Against</th><th>Difference</th></tr></thead><tbody><?php foreach($s->fetchAll() as $i=>$r):$diff=(int)$r['score_for']-(int)$r['score_against'];?><tr><td><strong>#<?=$i+1?></strong></td><td><strong><?=e($r['name'])?></strong><small style="display:block;color:var(--text-secondary)"><?=e($r['institution'])?></small></td><td><?=$r['played']?></td><td><?=$r['wins']?></td><td><?=$r['losses']?></td><td><?=$r['score_for']?></td><td><?=$r['score_against']?></td><td class="<?=$diff>=0?'positive':'negative'?>"><?=$diff>0?'+':''?><?=$diff?></td></tr><?php endforeach;?></tbody></table></div></div></section></main><?php require __DIR__.'/includes/footer.php';?>
